// The run's 3D view as the app ships it: its sources (apps/desktop/renderer/run3d/) compile into one classic
// script (scripts/build-3d.js, built in memory here) that the renderer's CSP accepts, the overlay
// (apps/desktop/renderer/run3d.js) loads it lazily from generated/, and the pieces around it stay in place:
// the 3D buttons beside Chat, the bundle generated and packed (never committed), poc/ left out.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { build } = require('../../../scripts/build-3d');

const ROOT = path.join(__dirname, '..', '..', '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');

test('the 3D view\'s sources compile into one script that defines window.Run3DScene, with no eval for the CSP', { timeout: 60000 }, async (t) => {
  const out = await build({ write: false });
  if (!out) { t.skip('esbuild is not installed'); return; }
  assert.match(out.code, /^\/\/ Generated by scripts\/build-3d\.js/, 'its header says where it comes from');
  assert.match(out.code, /window\.Run3DScene\s*=/);
  assert.doesNotMatch(out.code, /\beval\(|new Function\(/, 'script-src \'self\' allows no eval');
  assert.doesNotMatch(out.code, /^\s*(import|export)\s/m, 'a classic script: no module syntax left');
});

test('the overlay loads the bundle on the first click, from generated/, with a plain script element', () => {
  const src = read('apps/desktop/renderer/run3d.js');
  assert.match(src, /const BUNDLE = '\.\.\/\.\.\/\.\.\/generated\/run3d-scene\.js';/);
  assert.match(src, /document\.createElement\('script'\)/);
  assert.doesNotMatch(read('apps/desktop/renderer/index.html'), /run3d-scene\.js/, 'not loaded when the app starts');
});

test('a 3D button sits beside Chat on the Run screen and in the run chat\'s header', () => {
  assert.match(read('apps/desktop/renderer/views/run/run.js'), /<button id="run-mode-3d"[^>]*data-run3d="run"/);
  assert.match(read('apps/desktop/renderer/views/runchat/runchat.js'), /<button id="rc-3d"[^>]*data-run3d="chat"/);
});

test('the bundle is generated (gitignored, built by the npm hooks), packed into the app; poc/ is not', () => {
  assert.match(read('.gitignore'), /^generated\/$/m);
  const scripts = JSON.parse(read('package.json')).scripts;
  for (const hook of ['prepare', 'prestart', 'prebuild']) assert.match(scripts[hook], /node scripts\/build-3d\.js/, hook);
  const pack = read('apps/desktop/scripts/package.js');
  assert.match(pack, /\|poc\|/, 'poc/ is left out of the package');
  assert.doesNotMatch(pack, /\|generated\|/, 'generated/ is packed');
});
